#!/usr/bin/env node
// make-photos.mjs: turns tee.png (a linen T-shirt) into 4 product photos with Modelfy
// and prints the links to the finished photos.
//
// Run with the key in .env:
//   node --env-file=.env make-photos.mjs
// The script reads MODELFY_API_KEY from the environment.

import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const MCP_URL = 'https://mcp-dev.modelfy.ai/mcp';
const PHOTO_PATH = join(dirname(fileURLToPath(import.meta.url)), 'tee.png');
const PRODUCT_NAME = 'Linen T-shirt';

// Photo settings: studio shot, product only (no model), 4 photos.
const PHOTO_SETTINGS = {
  mode: 'studio',
  background_color: 'white',
  aspect_ratio: '4:5',
  photos_per_product: 4,
  direction: 'clean product photo, soft even light, the shirt flat and fully visible',
  locale: 'en',
};

const KEY = process.env.MODELFY_API_KEY;
if (!KEY) {
  console.error('MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs');
  process.exit(1);
}

let nextId = 1;
let sessionId; // Mcp-Session-Id, if the server sends one

function headers() {
  return {
    Authorization: `Bearer ${KEY}`,
    'Content-Type': 'application/json',
    Accept: 'application/json, text/event-stream',
    ...(sessionId ? { 'Mcp-Session-Id': sessionId } : {}),
  };
}

// Reads a JSON-RPC reply sent either as plain JSON or as a server-sent event.
function parseReply(text, contentType) {
  if (contentType.includes('text/event-stream')) {
    const dataLines = text.split('\n').filter((l) => l.startsWith('data:')).map((l) => l.slice(5).trim());
    if (dataLines.length === 0) throw new Error(`Empty event stream from Modelfy: ${text.slice(0, 300)}`);
    return JSON.parse(dataLines[dataLines.length - 1]);
  }
  return JSON.parse(text);
}

async function post(body) {
  const res = await fetch(MCP_URL, { method: 'POST', headers: headers(), body: JSON.stringify(body) });
  const sid = res.headers.get('mcp-session-id');
  if (sid) sessionId = sid;
  const text = await res.text();
  if (!res.ok) throw new Error(`Modelfy HTTP ${res.status}: ${text.slice(0, 300)}`);
  return text.trim() ? parseReply(text, res.headers.get('content-type') ?? '') : null;
}

async function initialize() {
  await post({
    jsonrpc: '2.0',
    id: nextId++,
    method: 'initialize',
    params: { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'make-photos', version: '1.0.0' } },
  });
  await post({ jsonrpc: '2.0', method: 'notifications/initialized' });
}

// Calls a tool and returns its structured result. Throws on tool errors.
async function callTool(name, args = {}) {
  const reply = await post({ jsonrpc: '2.0', id: nextId++, method: 'tools/call', params: { name, arguments: args } });
  if (reply?.error) throw new Error(`${name}: ${reply.error.message}`);
  const result = reply.result;
  if (result.isError) {
    const err = result.structuredContent?.error ?? {};
    throw new Error(`${name} failed (${err.code ?? 'ERROR'}): ${err.message ?? result.content?.[0]?.text}. ${err.next_step ?? ''}`.trim());
  }
  return result.structuredContent ?? JSON.parse(result.content.find((c) => c.type === 'text' && c.text.startsWith('{'))?.text ?? '{}');
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function uploadProductPhoto() {
  const bytes = await readFile(PHOTO_PATH);
  const contentType = 'image/png';

  const session = await callTool('create_upload_session', {
    files: [{ content_type: contentType, bytes: bytes.length }],
  });
  const file = session.uploads[0];
  const put = await fetch(file.put_url, { method: 'PUT', headers: file.headers, body: bytes });
  if (!put.ok) throw new Error(`Upload of tee.png failed: HTTP ${put.status}`);

  for (let attempt = 0; attempt < 30; attempt++) {
    const status = await callTool('get_uploaded_photos', { session_id: session.session_id });
    const ready = status.ready ?? [];
    if (ready.length > 0) return ready[0].upload_id ?? ready[0];
    if (!status.pending) throw new Error(`tee.png was rejected: ${JSON.stringify(status.rejected ?? status)}`);
    await sleep(1000);
  }
  throw new Error('Timed out waiting for tee.png to arrive at Modelfy');
}

async function main() {
  await initialize();

  const account = await callTool('get_account');
  console.log(`Account: ${account.plan}, ${account.credits} credits${account.sandbox ? ' (sandbox: nothing is spent, photos are samples)' : ''}`);

  console.log(`Uploading ${PHOTO_PATH} ...`);
  const uploadId = await uploadProductPhoto();

  const plan = await callTool('plan_photos', {
    products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
    ...PHOTO_SETTINGS,
  });
  console.log(`Plan: 4 photos for ${plan.credits} credits (balance ${plan.balance}).`);
  if (!plan.enough_credits) throw new Error('Not enough credits for this session.');

  const launch = await callTool('generate_photos', { quote_id: plan.quote_id, user_confirmed: true });
  const session = launch.session_id;
  console.log(`Session ${session} started.`);

  let photoSession;
  for (let attempt = 0; attempt < 40; attempt++) {
    photoSession = await callTool('get_photo_session', { session_id: session, wait_seconds: 45 });
    if (photoSession.status !== 'running') break;
    console.log(`  still running...`);
  }
  if (photoSession.status === 'running') throw new Error(`Session ${session} is still running; check it later with get_photo_session.`);

  console.log(`Status: ${photoSession.status}`);
  const photos = photoSession.photos ?? [];
  for (const p of photos) {
    console.log(p.url ?? p.link ?? JSON.stringify(p));
  }
  if (photoSession.web_url) console.log(`All photos: ${photoSession.web_url}`);
  if (photos.length === 0) throw new Error('No photos came back.');
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

